begin;
create function private.staff_enabled() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from core.user_event_roles where user_id=private.actor() and event_id=private.event_id()) $$;
create function private.audit_access(c uuid) returns boolean language sql stable security definer set search_path='' as $$ select private.has_role('judgeAdvisor') and not private.has_role('admin') and exists(select 1 from judging.cycles where id=c and event_id=private.event_id() and state='closed' and purge_due_at>now()) $$;
grant usage on schema private,audit to authenticated;
grant select on core.events,core.users,core.user_event_roles,core.teams,core.team_pit_locations,judging.cycles,judging.panels,judging.members,judging.participations,judging.observations,judging.flags,filming.categories,filming.items,filming.templates,filming.shots,messaging.pages,messaging.responses,audit.entries to authenticated;
create policy event_read on core.events for select to authenticated using(active and private.staff_enabled());
create policy users_read on core.users for select to authenticated using(id=private.actor() or private.has_role('admin') or (not private.has_role('admin') and private.has_role('judgeAdvisor')) or exists(select 1 from judging.members m where m.user_id=core.users.id and private.judging_access(m.cycle_id,m.panel_id)));
create policy roles_read on core.user_event_roles for select to authenticated using(event_id=private.event_id() and (user_id=private.actor() or private.has_role('admin')));
create policy teams_read on core.teams for select to authenticated using(private.staff_enabled());
create policy pits_read on core.team_pit_locations for select to authenticated using(event_id=private.event_id() and private.staff_enabled());
create policy cycle_read on judging.cycles for select to authenticated using(private.judging_access(id) or private.audit_access(id));
create policy panel_read on judging.panels for select to authenticated using(private.judging_access(cycle_id,id) or private.audit_access(cycle_id));
create policy members_read on judging.members for select to authenticated using(private.judging_access(cycle_id,panel_id) or private.audit_access(cycle_id));
create policy participation_read on judging.participations for select to authenticated using(private.judging_access(cycle_id,panel_id) or private.audit_access(cycle_id));
create policy observations_read on judging.observations for select to authenticated using(private.judging_access(cycle_id,panel_id) or private.audit_access(cycle_id));
create policy flags_read on judging.flags for select to authenticated using(exists(select 1 from judging.participations t where t.cycle_id=flags.cycle_id and t.team_id=flags.team_id and (private.judging_access(t.cycle_id,t.panel_id) or private.audit_access(t.cycle_id))));
create policy categories_read on filming.categories for select to authenticated using(event_id=private.event_id() and (private.has_role('filmmaker') or private.has_role('admin')));
create policy items_read on filming.items for select to authenticated using(event_id=private.event_id() and (private.has_role('filmmaker') or private.has_role('admin')));
create policy templates_read on filming.templates for select to authenticated using(event_id=private.event_id() and (private.has_role('filmmaker') or private.has_role('admin')));
create policy shots_read on filming.shots for select to authenticated using(event_id=private.event_id() and (private.has_role('filmmaker') or private.has_role('admin')));
create policy pages_read on messaging.pages for select to authenticated using(event_id=private.event_id() and ((source_area='filming' and (private.has_role('filmmaker') or private.has_role('admin'))) or (source_area='judges' and exists(select 1 from judging.participations t where t.cycle_id=pages.cycle_id and t.team_id=pages.team_id and private.judging_access(t.cycle_id,t.panel_id)))));
create policy responses_read on messaging.responses for select to authenticated using(exists(select 1 from messaging.pages where id=page_id));
create policy audit_read on audit.entries for select to authenticated using(private.audit_access(cycle_id));
create function api.me() returns jsonb language sql stable security invoker set search_path='' as $$ select jsonb_build_object('id',u.id,'email',u.email,'name',u.name,'version',u.version,'roles',coalesce((select jsonb_agg(role order by role) from core.user_event_roles where user_id=u.id and event_id=private.event_id()),'[]'::jsonb)) from core.users u where u.id=private.actor() $$;
create function api.schedule() returns jsonb language sql stable security invoker set search_path='' as $$ select jsonb_build_object('url',schedule_url) from core.events where active $$;
create function api.teams_list(p_limit integer default 50,p_after uuid default null,p_search text default '') returns jsonb language sql stable security invoker set search_path='' as $$ select coalesce(jsonb_agg(jsonb_build_object('id',id,'officialId',official_id,'name',name,'country',country,'countryCode',country,'version',version) order by id),'[]'::jsonb) from(select * from core.teams where (p_after is null or id>p_after) and (name ilike '%'||p_search||'%' or official_id ilike '%'||p_search||'%') order by id limit greatest(1,least(p_limit,100))) t $$;
create function api.panels_list(p_limit integer default 50,p_after uuid default null) returns jsonb language sql stable security invoker set search_path='' as $$ select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'leaderId',p.leader_id,'version',p.version,'judgeIds',coalesce((select jsonb_agg(user_id order by user_id) from judging.members where panel_id=p.id),'[]'::jsonb)) order by p.id),'[]'::jsonb) from(select * from judging.panels where private.judging_access(cycle_id,id) and (p_after is null or id>p_after) order by id limit greatest(1,least(p_limit,100))) p $$;
create function api.participations_list(p_limit integer default 50,p_after uuid default null) returns jsonb language sql stable security invoker set search_path='' as $$ select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'teamId',p.team_id,'panelId',p.panel_id,'evaluationStatus',p.evaluation_state,'participationStatus',p.state,'hasHistory',p.has_history,'version',p.version,'withdrawalReason',coalesce(p.withdrawal_reason,''),'flags',coalesce((select jsonb_agg(jsonb_build_object('type',type,'reason',coalesce(reason,''),'version',version)) from judging.flags where cycle_id=p.cycle_id and team_id=p.team_id),'[]'::jsonb),'team',jsonb_build_object('id',t.id,'officialId',t.official_id,'name',t.name,'country',t.country,'countryCode',t.country,'version',t.version)) order by p.id),'[]'::jsonb) from(select * from judging.participations where private.judging_access(cycle_id,panel_id) and (p_after is null or id>p_after) order by id limit greatest(1,least(p_limit,100))) p join core.teams t on t.id=p.team_id $$;
create function api.observations_list(p_team uuid) returns jsonb language sql stable security invoker set search_path='' as $$ select coalesce(jsonb_agg(jsonb_build_object('id',o.id,'authorId',o.author_id,'authorName',coalesce(u.name,u.email),'panelId',o.panel_id,'teamId',o.team_id,'text',o.notes,'version',o.version,'updatedAt',o.updated_at) order by o.id),'[]'::jsonb) from judging.observations o join core.users u on u.id=o.author_id where o.team_id=p_team and private.judging_access(o.cycle_id,o.panel_id) $$;
create function api.categories_list(p_limit integer default 50,p_after uuid default null) returns jsonb language sql stable security invoker set search_path='' as $$ select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'version',version) order by id),'[]'::jsonb) from(select * from filming.categories where p_after is null or id>p_after order by id limit greatest(1,least(p_limit,100))) c $$;
create function api.items_list(p_limit integer default 50,p_after uuid default null) returns jsonb language sql stable security invoker set search_path='' as $$ select coalesce(jsonb_agg(jsonb_build_object('id',id,'categoryId',category_id,'title',title,'doneAt',done_at,'doneBy',done_by,'version',version) order by id),'[]'::jsonb) from(select * from filming.items where p_after is null or id>p_after order by id limit greatest(1,least(p_limit,100))) c $$;
create function api.tracker(p_limit integer default 50,p_after uuid default null) returns jsonb language sql stable security invoker set search_path='' as $$ select jsonb_build_object('templates',coalesce((select jsonb_agg(jsonb_build_object('id',id,'name',name) order by id) from filming.templates),'[]'::jsonb),'teams',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'officialId',t.official_id,'name',t.name,'country',t.country,'countryCode',t.country,'version',t.version,'shots',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'templateId',s.template_id,'teamId',s.team_id,'status',s.status,'notes',s.notes,'capturedAt',s.captured_at,'capturedBy',s.captured_by,'version',s.version)) from filming.shots s where s.team_id=t.id),'[]'::jsonb)) order by t.id) from(select * from core.teams where (p_after is null or id>p_after) and (private.has_role('filmmaker') or private.has_role('admin')) order by id limit greatest(1,least(p_limit,100))) t),'[]'::jsonb)) $$;
create function private.page_delivery_status(page uuid) returns text language plpgsql stable security definer set search_path='' as $$ declare p messaging.pages;begin
 select * into p from messaging.pages where id=page and event_id=private.event_id();
 if p.id is null then return null;end if;
 if p.source_area='filming' then if not(private.has_role('filmmaker') or private.has_role('admin')) then return null;end if;
 elsif not exists(select 1 from judging.participations where cycle_id=p.cycle_id and team_id=p.team_id and private.judging_access(cycle_id,panel_id)) then return null;end if;
 if exists(select 1 from messaging.responses where page_id=p.id) then return 'responded';end if;
 if p.cancelled_at is not null then return 'cancelled';end if;
 if p.scheduled_for>now() then return 'scheduled';end if;
 if exists(select 1 from private.deliveries where page_id=p.id and status='failed') then return 'failed';end if;
 if exists(select 1 from private.deliveries where page_id=p.id and status in ('queued','leased')) then return 'queued';end if;
 if exists(select 1 from private.deliveries where page_id=p.id and status='accepted') then return 'accepted';end if;
 if exists(select 1 from private.deliveries where page_id=p.id and status='cancelled') then return 'cancelled';end if;
 return 'no_devices';end $$;
create function api.pages_list(p_limit integer default 50,p_after uuid default null,p_source_area text default null) returns jsonb language sql stable security invoker set search_path='' as $$ select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'teamId',p.team_id,'sourceArea',p.source_area,'message',p.message,'scheduledFor',p.scheduled_for,'createdAt',p.created_at,'version',p.version,'response',r.response,'respondedAt',r.created_at,'deliveryStatus',private.page_delivery_status(p.id)) order by p.id),'[]'::jsonb) from(select * from messaging.pages where (p_after is null or id>p_after) and (p_source_area is null or source_area=p_source_area) order by id limit greatest(1,least(p_limit,100))) p left join messaging.responses r on r.page_id=p.id $$;
create function api.judging_audit() returns jsonb language sql stable security invoker set search_path='' as $$ select jsonb_build_object('cycles',coalesce((select jsonb_agg(to_jsonb(c)) from judging.cycles c where private.audit_access(c.id)),'[]'::jsonb),'observations',coalesce((select jsonb_agg(to_jsonb(o)) from judging.observations o where private.audit_access(o.cycle_id)),'[]'::jsonb),'entries',coalesce((select jsonb_agg(to_jsonb(e)) from audit.entries e),'[]'::jsonb)) $$;
create function api.mentor_me(p_token_hash text) returns jsonb language plpgsql security definer set search_path='' as $$ declare s private.mentor_sessions:=private.mentor(p_token_hash);r jsonb;begin select jsonb_build_object('team',jsonb_build_object('id',t.id,'officialId',t.official_id,'name',t.name,'country',t.country,'countryCode',t.country,'version',t.version),'event',jsonb_build_object('id',e.id,'name',e.name),'expiresAt',s.expires_at) into r from core.teams t join core.events e on e.id=s.event_id where t.id=s.team_id;return r;end $$;
create function api.mentor_pages(p_token_hash text,p_installation_id uuid,p_limit integer default 50,p_after uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$ declare s private.mentor_sessions:=private.mentor(p_token_hash);r jsonb;begin
 select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'teamId',p.team_id,'sourceArea',p.source_area,'message',p.message,'scheduledFor',p.scheduled_for,'createdAt',p.created_at,'version',p.version,'response',pr.response,'respondedAt',pr.created_at,'deliveryId',(select d.id from private.deliveries d join private.push_devices pd on pd.id=d.device_id where d.page_id=p.id and pd.installation_id=p_installation_id and pd.session_id=s.id)) order by p.id),'[]'::jsonb) into r from(select * from messaging.pages where event_id=s.event_id and team_id=s.team_id and scheduled_for<=now() and cancelled_at is null and (expires_at is null or expires_at>now()) and (cycle_id is null or exists(select 1 from judging.cycles where id=cycle_id and state='active')) and (p_after is null or id>p_after) order by id limit greatest(1,least(p_limit,100))) p left join messaging.responses pr on pr.page_id=p.id;return r;end $$;
create function api.mentor_filming(p_token_hash text) returns jsonb language plpgsql security definer set search_path='' as $$ declare s private.mentor_sessions:=private.mentor(p_token_hash);r jsonb;begin select coalesce(jsonb_agg(jsonb_build_object('templateId',t.id,'name',t.name,'status',coalesce(sh.status,'pending')) order by t.id),'[]'::jsonb) into r from filming.templates t left join filming.shots sh on sh.template_id=t.id and sh.team_id=s.team_id where t.event_id=s.event_id;return r;end $$;
commit;

